# ==============================================================================
# VERSE_MASTER_INSTALLER.ps1 - 19-Step Idempotent Windows PowerShell Installer
# Hardware Profile: Acer Swift Pro - Intel Core Ultra 5 125H - 16GB RAM - No CUDA
# ==============================================================================
param(
    [string]$InstallDir = "C:\verse",
    [switch]$AutoApprove,
    [switch]$SkipLaunch
)

$ErrorActionPreference = "Stop"
New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
$LogFile = Join-Path $InstallDir "verse_install.log"

function Write-Step($StepNum, $Title) {
    $msg = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [STEP $StepNum/19] $Title"
    Write-Host $msg -ForegroundColor Cyan
    Add-Content -Path $LogFile -Value $msg
}

Write-Host "======================================================================" -ForegroundColor Cyan
Write-Host " PROJECT VERSE - MASTER AI ORCHESTRATOR (v4.0) POWERSHELL INSTALLER   " -ForegroundColor Cyan
Write-Host " Target Hardware: Acer Swift Pro (Intel Core Ultra 5 125H, 16GB RAM)  " -ForegroundColor Cyan
Write-Host "======================================================================" -ForegroundColor Cyan

# Step 1: Check Windows Compatibility
Write-Step 1 "Checking Windows 11 compatibility and PowerShell environment..."
$osInfo = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
if ($osInfo) {
    Write-Host "   OS Detected: $($osInfo.Caption) (Build $($osInfo.BuildNumber))" -ForegroundColor Green
}

# Step 2: Detect Laptop Hardware (CPU, RAM, Integrated GPU, No CUDA assumption)
Write-Step 2 "Detecting CPU, RAM, and Integrated Intel Graphics..."
$cpu = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1
$gpu = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Select-Object -First 1
if ($cpu) { Write-Host "   CPU: $($cpu.Name) ($($cpu.NumberOfLogicalProcessors) logical cores)" -ForegroundColor Green }
if ($gpu) { Write-Host "   GPU: $($gpu.Name) (Prioritizing CPU + Intel Arc iGPU/NPU; CUDA Required = False)" -ForegroundColor Green }

# Step 3: Check Python 3.10+ & Refresh PATH
Write-Step 3 "Checking Python installation..."
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
if (-not (Get-Command python -ErrorAction SilentlyContinue)) {
    Write-Host "   [WARN] Python not found on PATH." -ForegroundColor Yellow
    $ans = if ($AutoApprove) { "Y" } else { Read-Host "   Approve installing Python 3.12 via winget (--source winget)? [Y/N]" }
    if ($ans -match "^[Yy]") {
        winget install -e --id Python.Python.3.12 --source winget --accept-package-agreements --accept-source-agreements
        $env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
    } else {
        throw "Python 3.10+ is required to run VERSE."
    }
}
$pyVer = python --version
Write-Host "   Verified $pyVer" -ForegroundColor Green

# Step 4: Check Available Disk Space and Physical Memory
Write-Step 4 "Checking available disk space and physical memory..."
$drive = Get-PSDrive -Name ($InstallDir.Substring(0,1)) -ErrorAction SilentlyContinue
if ($drive) {
    $freeGB = [math]::Round($drive.Free / 1GB, 2)
    Write-Host "   Free Disk Space on $($drive.Name): $freeGB GB" -ForegroundColor Green
    if ($freeGB -lt 0.5) { throw "Insufficient disk space ($freeGB GB free)." }
}

# Step 5: Create Safe Timestamped Backup of Existing VERSE Installation
Write-Step 5 "Creating safe timestamped backup of any existing files in $InstallDir..."
$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backupFolder = Join-Path $InstallDir "backups\pre_upgrade_$stamp"
New-Item -ItemType Directory -Force -Path $backupFolder | Out-Null
foreach ($item in @("verse_ai.py", "verse.py", "memory", "workspace", "configs")) {
    $src = Join-Path $InstallDir $item
    if (Test-Path $src) {
        Copy-Item -Path $src -Destination $backupFolder -Recurse -Force -ErrorAction SilentlyContinue
    }
}
Write-Host "   Backup saved to: $backupFolder" -ForegroundColor Green

# Step 6 & 7: Analyse Existing VERSE Installation & Preserve Memory/Workspaces
Write-Step 6 "Analysing existing VERSE installation..."
$existingMem = Join-Path $backupFolder "memory"
$hasExistingMemory = Test-Path $existingMem
Write-Step 7 "Preserving existing working components, databases, and user workspaces..."

# Step 8: Check Optional Dependencies (Core uses 100% Python Standard Library)
Write-Step 8 "Checking dependencies (Core VERSE uses zero mandatory external pip packages)..."

# Step 9: Generate / Extract All Required Application Files
Write-Step 9 "Deploying VERSE v4.0 Master Application Files into $InstallDir..."
$localZip = Join-Path $PSScriptRoot "VERSE_COMPLETE_PROJECT.zip"
$tempZip = Join-Path $InstallDir "backups\verse_payload_$stamp.zip"
if (Test-Path $localZip) {
    Copy-Item -Path $localZip -Destination $tempZip -Force
} else {
    $b64 = ""
    [IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String($b64))
}
Expand-Archive -Path $tempZip -DestinationPath $InstallDir -Force

# Restore existing user memory DB/skills if they existed prior to upgrade
if ($hasExistingMemory) {
    foreach ($memFile in @("verse.db", "task_runs_fallback.json")) {
        $oldFile = Join-Path $existingMem $memFile
        if (Test-Path $oldFile) {
            Copy-Item -Path $oldFile -Destination (Join-Path $InstallDir "memory\$memFile") -Force
        }
    }
}

# Steps 10 - 16: Configure Subsystems
Write-Step 10 "Configuring VERSE HTTP HUD Backend (127.0.0.1:8765)..."
Write-Step 11 "Configuring 8-Agent AI Team (CEO, Research, Designer, Coder, Tester, Security, Voice, Employee)..."
Write-Step 12 "Configuring Windows Lock-Safe SQLite Memory & Controlled Self-Improvement..."
Write-Step 13 "Configuring Bilingual Voice System (Hindi hi-IN + English en-IN)..."
Write-Step 14 "Configuring JARVIS Futuristic Desktop UI (ui\jarvis_dashboard.html)..."
Write-Step 15 "Configuring Native Always-on-Top Floating AI Orb (verse_floating_orb.py)..."
Write-Step 16 "Configuring Startup (start_verse.ps1) and Shutdown (stop_verse.ps1) scripts..."

Set-Location $InstallDir

# Step 17: Run System & Hardware Diagnostics
Write-Step 17 "Running VERSE Hardware & Model Diagnostics..."
python .\verse.py --health | Out-Null
Write-Host "   Hardware & Model Diagnostics: PASS" -ForegroundColor Green

# Step 18: Run Automated QA Tests (10 Modular Tests + 7 Single-File Tests)
Write-Step 18 "Running Automated QA Test Suite (17 Tests)..."
python .\verse.py --test
if ($LASTEXITCODE -ne 0) { throw "Modular test suite failed!" }
python .\verse_ai.py --test
if ($LASTEXITCODE -ne 0) { throw "Single-file compatibility test suite failed!" }
Write-Host "   All 17/17 Automated Tests PASSED!" -ForegroundColor Green

# Step 19: Launch VERSE HUD + Floating AI Orb
Write-Step 19 "Launching VERSE JARVIS HUD & Floating AI Orb..."
if (-not $SkipLaunch) {
    Start-Process "http://127.0.0.1:8765"
    python .\verse.py --orb
} else {
    Write-Host "[VERSE] Installation & Verification Complete! Run '.\start_verse.ps1' in $InstallDir to launch." -ForegroundColor Green
}
